<section class="space-y-3 rounded-xl border p-4" x-show="jobs.some(j=>editableJob(j))">
<div class="flex items-center justify-between gap-3"><h3 class="font-serif text-xl">Pending audio</h3><button type="button" class="btn-primary" :disabled="batchBusy||jobBusy||!pendingJobs.length" @click="startPending()" x-text="batchBusy?batchProgress:'Generate all pending ('+pendingJobs.length+')'"></button></div>
<template x-for="j in jobs.filter(j=>editableJob(j))" :key="j.id"><div class="flex flex-wrap items-center gap-3 rounded border p-3"><div class="min-w-0 flex-1"><p class="font-semibold" x-text="j.name"></p><p class="text-xs" x-text="(categories[j.category]||j.category)+' · '+j.model+' · '+(j.settings?.voice||'Default voice')+' · '+(j.status==='draft'?'Pending':'Queued')"></p><p class="mt-1 line-clamp-2 text-sm" x-text="j.prompt"></p></div><button type="button" class="btn-secondary" :disabled="batchBusy||jobBusy" @click="editJob(j)">Edit</button><button type="button" class="btn-secondary" :disabled="batchBusy||jobBusy" @click="deleteJob(j)">Delete</button><button type="button" class="btn-primary" x-show="j.status==='draft'" :disabled="batchBusy||jobBusy" @click="generateDraft(j)">Generate</button></div></template>
</section>
<template x-teleport="body"><dialog x-ref="audioJobDialog" class="reference-dialog image-picker-dialog rounded-xl border bg-white text-stone-900 dark:bg-stone-900 dark:text-stone-100" @click="if($event.target===$el)$el.close()"><div class="flex flex-col"><header class="flex items-center justify-between border-b px-6 py-4"><h3 class="font-serif text-xl">Edit pending audio</h3><button type="button" class="btn-secondary" @click="$refs.audioJobDialog.close()">Close</button></header><template x-if="editingJob"><div class="min-h-0 space-y-4 overflow-y-auto px-6 py-5">
<label class="field">Name<input x-model="editingJob.name" maxlength="160"></label><label class="field">Text / prompt<textarea x-model="editingJob.prompt" maxlength="5000" rows="4"></textarea></label>
<label class="field">Category<select x-model="editingJob.category"><template x-for="(name,key) in categories" :key="key"><option :value="key" x-text="name"></option></template></select></label>
<label class="field">Model<select x-model="editingJob.model" @change="editingJob.settings={voice:draftVoices[0]||''}"><template x-for="m in voiceModels" :key="m.id"><option :value="m.id" x-text="m.name"></option></template><option value="fal-ai/stable-audio">Stable Audio</option><option value="cassetteai/sound-effects-generator">CassetteAI sound effects</option></select></label>
<template x-if="draftVoices.length"><div class="space-y-3"><label class="field">Voice<select x-model="editingJob.settings.voice"><option value="">Default voice</option><template x-for="v in draftVoices" :key="v"><option :value="v" x-text="v"></option></template></select></label><div x-show="editingJob.model.startsWith('google/')" class="space-y-3"><label class="field">Delivery instructions<textarea x-model="editingJob.settings.instructions" maxlength="1000"></textarea></label><label class="field">Temperature<input type="number" min="0" max="2" step="0.1" x-model.number="editingJob.settings.temperature"></label></div><label class="field" x-show="editingJob.model.startsWith('heygen/')">Language<input x-model="editingJob.settings.language" maxlength="10"></label></div></template>
<label class="field" x-show="editingJob.model.startsWith('fal-ai/')||editingJob.model.startsWith('cassetteai/')">Duration (seconds)<input type="number" min="1" :max="editingJob.model.startsWith('cassetteai/')?30:47" x-model.number="editingJob.seconds"></label>
</div></template><footer class="flex justify-end border-t px-6 py-4"><button type="button" class="btn-primary" :disabled="jobBusy" @click="saveJob()">Save pending audio</button></footer></div></dialog></template>
